data.services = [
  make('vehicle-sales', 'Vehicle Sales', 'بيع السيارات', 'A carefully selected collection. A personal approach to finding your next exceptional drive.', 'مجموعة منتقاة بعناية ونهج شخصي لمساعدتك على اختيار سيارتك الاستثنائية القادمة.', { icon: 'CarFront', image: photos.mercedes, category_en: 'Discover', category_ar: 'اكتشف', benefits_en: ['A curated selection of premium vehicles', 'Clear vehicle history and condition information', 'Personal viewings and considered test drives', 'Guidance from selection through handover'], benefits_ar: ['تشكيلة منتقاة من السيارات الفاخرة', 'معلومات واضحة عن تاريخ السيارة وحالتها', 'معاينات شخصية وتجارب قيادة مدروسة', 'إرشاد من مرحلة الاختيار حتى التسليم'], process_en: ['Tell us how you drive and what matters to you.', 'Explore a shortlist with your dedicated advisor.', 'Review the vehicle condition and available documentation.', 'Confirm the details and enjoy a considered handover.'], process_ar: ['أخبرنا عن أسلوب قيادتك وأولوياتك.', 'استعرض قائمة مختصرة مع مستشارك.', 'راجع حالة السيارة والوثائق المتاحة.', 'اعتمد التفاصيل واستمتع بتجربة تسليم مميزة.'], content_en: 'The right vehicle should fit your life as naturally as it captures your imagination. Our advisors take time to understand your priorities, from everyday comfort and passenger space to driving character and ownership costs.\n\nEvery vehicle is presented with available history, a clear description of its condition, and the information you need to make an informed decision. We welcome independent inspections and explain what is included in the sale before you commit.\n\nAvailability, specification, pricing, and any warranty coverage are confirmed individually. Contact our team for the current collection and an appointment tailored to your interests.', content_ar: 'السيارة المناسبة تنسجم مع حياتك بقدر ما تثير شغفك. يمنحك مستشارونا الوقت لفهم أولوياتك، من الراحة والمساحة إلى متعة القيادة وتكاليف الملكية.\n\nنعرض كل سيارة مع تاريخها المتاح ووصف واضح لحالتها والمعلومات التي تساعدك على اتخاذ قرار واعٍ. نرحب بالفحص المستقل ونشرح ما يشمله البيع قبل الالتزام.\n\nيتم تأكيد التوافر والمواصفات والسعر وأي ضمان لكل سيارة على حدة. تواصل مع فريقنا للاطلاع على المجموعة الحالية وترتيب موعد يناسب اهتماماتك.' }),
  make('maintenance-service', 'Maintenance & Service', 'الصيانة والخدمة', 'Thoughtful maintenance and precise diagnostics to keep every journey running smoothly.', 'صيانة مدروسة وتشخيص دقيق لتبقى كل رحلة سلسة وآمنة.', { icon: 'Wrench', image: photos.service, category_en: 'Maintain', category_ar: 'صيانة', benefits_en: ['Maintenance matched to your manufacturer schedule', 'Digital diagnostics and clear findings', 'Written estimates before approved work begins', 'A documented service history'], benefits_ar: ['صيانة متوافقة مع جدول الشركة المصنعة', 'تشخيص رقمي ونتائج واضحة', 'تقديرات مكتوبة قبل بدء العمل المعتمد', 'سجل صيانة موثق'], process_en: ['Share your vehicle details and any symptoms.', 'Our team inspects and diagnoses the concern.', 'Review the estimate and approve the scope.', 'Collect your vehicle with a clear service report.'], process_ar: ['شارك تفاصيل سيارتك وأي أعراض لاحظتها.', 'يفحص فريقنا السيارة ويشخص المشكلة.', 'راجع التقدير واعتمد نطاق العمل.', 'استلم سيارتك مع تقرير خدمة واضح.'], content_en: 'Regular care protects the everyday experience of owning a premium vehicle. We plan maintenance around the vehicle manufacturer’s recommendations, mileage, age, and how the car is used. Oil services, filters, brakes, cooling systems, and essential checks all receive considered attention.\n\nFor a warning light, unusual noise, or change in performance, diagnosis comes before parts replacement. We explain what we found, what is urgent, and what can be planned for later. No additional work starts without your approval.\n\nYour service advisor confirms parts availability and the expected completion time after inspection. When the work is complete, you receive a record of the service and practical advice for the miles ahead.', content_ar: 'تحافظ العناية المنتظمة على متعة امتلاك سيارة فاخرة. نخطط للصيانة وفق توصيات الشركة المصنعة والمسافة المقطوعة وعمر السيارة وطريقة استخدامها، مع اهتمام بالزيوت والفلاتر والفرامل والتبريد والفحوص الأساسية.\n\nعند ظهور ضوء تحذير أو صوت غير معتاد أو تغير في الأداء، يأتي التشخيص قبل استبدال القطع. نشرح النتائج وما يحتاج إلى عناية عاجلة وما يمكن التخطيط له لاحقاً. لا نبدأ أي عمل إضافي دون موافقتك.\n\nيؤكد مستشار الخدمة توافر القطع وموعد الإنجاز المتوقع بعد الفحص. وعند انتهاء العمل تتلقى سجلاً للخدمة ونصائح عملية للرحلات القادمة.' }),
  make('premium-detailing', 'Premium Detailing', 'العناية الفاخرة بالمظهر', 'Restore depth, clarity, and character with meticulous care for every surface.', 'استعد عمق اللون ونقاء اللمعان وجمال التفاصيل بعناية دقيقة لكل سطح.', { icon: 'Sparkles', image: photos.detail, category_en: 'Protect', category_ar: 'حماية', benefits_en: ['Safe cleaning techniques for sensitive finishes', 'Paint assessment before correction', 'Tailored interior material care', 'Protection options explained clearly'], benefits_ar: ['تقنيات تنظيف آمنة للأسطح الحساسة', 'تقييم الطلاء قبل المعالجة', 'عناية مخصصة بمواد المقصورة', 'شرح واضح لخيارات الحماية'], process_en: ['Assess the paint, trim, wheels, and interior.', 'Choose a package suited to the condition.', 'Complete cleaning, correction, and protection as agreed.', 'Review the finish and your aftercare routine.'], process_ar: ['تقييم الطلاء والزينة والعجلات والمقصورة.', 'اختيار باقة تناسب حالة السيارة.', 'تنفيذ التنظيف والمعالجة والحماية المتفق عليها.', 'مراجعة النتيجة وخطة العناية اللاحقة.'], content_en: 'A premium finish starts with careful preparation. We assess the condition of the paint, trim, wheels, glass, and cabin before recommending a detailing approach. Gentle wash methods and controlled decontamination help prepare the surfaces for the next stage.\n\nWhere suitable, paint correction can reduce visible swirls and restore clarity. We discuss the likely result and the limits imposed by the existing paint. Interior work respects the needs of leather, fabric, delicate trim, and touchscreens.\n\nSealants and coating options can make future cleaning easier when maintained correctly. We explain cure times and aftercare, and never present a protective finish as a substitute for regular washing or careful use.', content_ar: 'تبدأ اللمسة الفاخرة بتحضير دقيق. نقيّم حالة الطلاء والزينة والعجلات والزجاج والمقصورة قبل اقتراح طريقة العناية المناسبة. ويساعد الغسيل اللطيف وإزالة الملوثات بحذر على تجهيز الأسطح للمرحلة التالية.\n\nعندما تكون حالة الطلاء مناسبة، يمكن للمعالجة تقليل آثار الدوامات واستعادة الوضوح. نناقش النتيجة المتوقعة والحدود التي يفرضها الطلاء الحالي. وتراعي عناية المقصورة احتياجات الجلد والأقمشة والزينة الحساسة والشاشات.\n\nقد تسهّل مواد الحماية والطلاءات عملية التنظيف اللاحقة عند صيانتها جيداً. نشرح أوقات الجفاف والعناية المطلوبة، ولا نقدم الحماية بديلاً للغسيل المنتظم والاستخدام الحريص.' }),
  make('vehicle-inspection', 'Vehicle Inspection', 'فحص السيارات', 'Make your next decision with a clear, independent view of your vehicle’s condition.', 'اتخذ قرارك القادم بثقة مع صورة واضحة ومستقلة عن حالة سيارتك.', { icon: 'ClipboardCheck', image: photos.bmw, category_en: 'Maintain', category_ar: 'صيانة', benefits_en: ['Structured mechanical and visual checks', 'Diagnostic scan where supported', 'A practical written findings report', 'Pre-purchase and ownership assessments'], benefits_ar: ['فحوص ميكانيكية وبصرية منظمة', 'مسح تشخيصي عندما تدعمه السيارة', 'تقرير نتائج مكتوب وعملي', 'تقييمات قبل الشراء وأثناء الملكية'], process_en: ['Confirm the vehicle and the purpose of inspection.', 'Agree the accessible inspection scope.', 'Carry out checks and an authorized road test where possible.', 'Discuss the findings and recommended next steps.'], process_ar: ['تأكيد بيانات السيارة وهدف الفحص.', 'الاتفاق على نطاق الفحص المتاح.', 'إجراء الفحوص وتجربة قيادة مصرح بها إن أمكن.', 'مناقشة النتائج والخطوات المقترحة.'], content_en: 'An inspection gives you a better picture of a vehicle at a particular point in time. It is especially useful before a purchase, ahead of a long journey, or when you want to plan maintenance with fewer surprises.\n\nWe assess accessible components, visible condition, fluid levels, tires, braking components, and electronic fault information where supported. A road test may be included with the owner’s permission and suitable conditions. Our findings distinguish observed issues from recommendations for further diagnosis.\n\nAn inspection is not a guarantee against future failures and cannot reveal every hidden defect. We explain the scope, inaccessible areas, and any limitations in the written report so you can make a measured decision.', content_ar: 'يمنحك الفحص صورة أوضح عن السيارة في وقت محدد. وهو مفيد قبل الشراء أو الرحلات الطويلة أو عند التخطيط للصيانة مع تقليل المفاجآت.\n\nنقيّم الأجزاء المتاحة والحالة الظاهرة ومستويات السوائل والإطارات ومكونات الفرامل ومعلومات الأعطال الإلكترونية عندما تدعمها السيارة. ويمكن إدراج تجربة قيادة بموافقة المالك وتوفر الظروف المناسبة. تميز نتائجنا بين المشكلات المرصودة والتوصيات بتشخيص إضافي.\n\nلا يمثل الفحص ضماناً ضد الأعطال المستقبلية ولا يكشف كل عيب خفي. نوضح نطاق العمل والمناطق غير المتاحة والقيود في التقرير المكتوب لمساعدتك على اتخاذ قرار متزن.' }),
  make('parts-accessories', 'Parts & Accessories', 'القطع والإكسسوارات', 'The right fit, the right quality, and expert guidance for your individual vehicle.', 'ملاءمة دقيقة وجودة مناسبة وإرشاد متخصص لسيارتك.', { icon: 'Settings', image: photos.wheel, category_en: 'Enhance', category_ar: 'تطوير', benefits_en: ['Compatibility checked against vehicle details', 'Original and approved-quality options explained', 'Clear availability and lead times', 'Installation support where appropriate'], benefits_ar: ['التحقق من التوافق مع بيانات السيارة', 'شرح خيارات القطع الأصلية والجودة المعتمدة', 'وضوح التوافر ومواعيد التوريد', 'دعم التركيب عند الحاجة'], process_en: ['Send the model, year, and vehicle identification details.', 'Review compatible options and a quotation.', 'Confirm the order and expected arrival.', 'Arrange collection or professional installation.'], process_ar: ['أرسل الطراز والسنة وبيانات تعريف السيارة.', 'راجع الخيارات المتوافقة وعرض السعر.', 'أكد الطلب وموعد الوصول المتوقع.', 'رتب الاستلام أو التركيب المتخصص.'], content_en: 'Small differences in specification can make a large difference to fit and performance. Our parts team checks compatibility using your vehicle details before recommending a component or accessory. Where alternatives exist, we explain the differences in origin, specification, availability, and coverage.\n\nFrom routine service items to practical cabin accessories, our focus is on parts suited to their intended use. Safety-related components receive particular attention to specification and installation requirements.\n\nSpecial-order lead times, returns eligibility, and any manufacturer warranty are confirmed before purchase. Ask our team about fitting support and whether calibration or additional work is needed after installation.', content_ar: 'قد تؤثر الفروق الصغيرة في المواصفات كثيراً على الملاءمة والأداء. يتحقق فريق القطع من التوافق باستخدام بيانات سيارتك قبل التوصية بأي قطعة أو إكسسوار. وعند وجود بدائل نشرح اختلاف المنشأ والمواصفات والتوافر والتغطية.\n\nمن مستلزمات الصيانة الدورية إلى إكسسوارات المقصورة العملية، نركز على القطع المناسبة لاستخدامها المقصود. وتحظى المكونات المرتبطة بالسلامة باهتمام خاص بالمواصفات ومتطلبات التركيب.\n\nنؤكد مدة توريد الطلبات الخاصة وشروط الإرجاع وأي ضمان مصنعي قبل الشراء. اسأل فريقنا عن دعم التركيب والحاجة إلى معايرة أو أعمال إضافية بعده.' }),
  make('roadside-assistance', 'Roadside Assistance', 'المساعدة على الطريق', 'Calm, practical support when an unexpected interruption changes your journey.', 'دعم هادئ وعملي عندما يغيّر عطل غير متوقع مسار رحلتك.', { icon: 'LifeBuoy', image: photos.road, category_en: 'Support', category_ar: 'دعم', benefits_en: ['A clear first point of contact', 'Assistance availability confirmed for your location', 'Recovery coordination where needed', 'Transparent guidance on next steps and costs'], benefits_ar: ['نقطة اتصال أولى واضحة', 'تأكيد توفر المساعدة في موقعك', 'تنسيق نقل السيارة عند الحاجة', 'إرشاد شفاف حول الخطوات والتكاليف'], process_en: ['Move to a safe place if it is possible to do so.', 'Contact us with your location and vehicle details.', 'Our team confirms available help, timing, and cost.', 'Receive assistance or arrange appropriate recovery.'], process_ar: ['انتقل إلى مكان آمن إذا كان ذلك ممكناً.', 'اتصل بنا وشارك موقعك وبيانات السيارة.', 'يؤكد فريقنا المساعدة المتاحة والوقت والتكلفة.', 'احصل على المساعدة أو رتب النقل المناسب.'], content_en: 'An unexpected stop is easier to manage with a clear plan. Our team helps assess the situation and coordinates available assistance for issues such as a flat battery, a tire concern, or a vehicle that needs recovery.\n\nTell us your exact location, vehicle details, and whether the vehicle is in a safe position. We confirm coverage, operating availability, expected response time, and any costs before arranging support. Some concerns require a recovery vehicle rather than a roadside repair.\n\nThis service does not replace emergency services. If there is immediate danger, an injury, a fire, or a hazardous road situation, contact the appropriate emergency authority first and follow their instructions.', content_ar: 'يسهل التعامل مع التوقف المفاجئ عندما توجد خطة واضحة. يساعد فريقنا على تقييم الموقف وتنسيق المساعدة المتاحة لمشكلات مثل البطارية أو الإطارات أو الحاجة إلى نقل السيارة.\n\nأخبرنا بموقعك الدقيق وبيانات السيارة وما إذا كانت في مكان آمن. نؤكد نطاق التغطية والتوافر ووقت الاستجابة المتوقع والتكاليف قبل ترتيب الدعم. بعض المشكلات تحتاج إلى ناقلة بدلاً من الإصلاح على الطريق.\n\nلا تحل هذه الخدمة محل خدمات الطوارئ. عند وجود خطر مباشر أو إصابة أو حريق أو وضع خطير على الطريق، اتصل بالجهة المختصة أولاً واتبع تعليماتها.' }),
];
