const blog = (slug, en, ar, de, da, image, categoryIndex, date, content_en, content_ar, tags_en, tags_ar) => make(slug, en, ar, de, da, { image, category_id: data.blog_categories[categoryIndex].id, category: data.blog_categories[categoryIndex].title_en, category_en: data.blog_categories[categoryIndex].title_en, category_ar: data.blog_categories[categoryIndex].title_ar, author: 'Apex Editorial Team', author_en: 'Apex Editorial Team', author_ar: 'فريق تحرير أبيكس', reading_time: 4, published_at: date, tags: tags_en, tags_en, tags_ar, content_en, content_ar });
data.blog_posts = [
  blog('the-art-of-preventive-maintenance', 'The art of preventive maintenance', 'فن الصيانة الوقائية', 'Small, well-timed decisions can make a meaningful difference to your driving experience.', 'قرارات صغيرة في الوقت المناسب تحدث فرقاً ملموساً في تجربة القيادة.', photos.service, 0, '2026-08-28',
    'Listen to the schedule, and to your car\n\nThe service schedule is the starting point for a dependable ownership routine. Consult the handbook for the correct intervals and remember that time matters as well as mileage. A car used for short urban journeys may have different needs from one that spends most of its time on open roads.\n\nMake a simple inspection a habit\n\nBetween professional visits, check tire pressure when the tires are cold, look for unusual fluid marks where you park, and pay attention to changes in starting, steering, or braking. Use the pressure values specified for your vehicle and load. If a warning appears, consult the handbook and seek appropriate advice before continuing.\n\nKeep records that tell a useful story\n\nSave invoices with the date, mileage, work completed, and parts used. A consistent record helps your technician recognize patterns and can make a future sale more straightforward. Ask for an explanation of recommended work, including what needs attention now and what can be planned.\n\nBuild a plan with your advisor\n\nA good maintenance conversation is specific to your car. Share how you use it, any recent changes, and journeys you have planned. At Apex Motors, we turn those details into a clear estimate and an agreed scope of work. The result is a service plan you can understand and follow.',
    'استمع إلى الجدول وإلى سيارتك\n\nجدول الصيانة هو نقطة البداية لروتين ملكية موثوق. راجع دليل السيارة لمعرفة الفترات الصحيحة وتذكر أن الوقت مهم بقدر المسافة. فالسيارة المستخدمة في رحلات قصيرة داخل المدينة قد تختلف احتياجاتها عن سيارة تقطع طرقاً مفتوحة باستمرار.\n\nاجعل الفحص البسيط عادة\n\nبين زيارات المختصين، تحقق من ضغط الإطارات وهي باردة، وابحث عن آثار سوائل غير معتادة في مكان الوقوف، وانتبه إلى تغيرات التشغيل والتوجيه والفرملة. استخدم قيم الضغط المحددة لسيارتك وحمولتها. وعند ظهور تحذير، راجع الدليل واطلب المشورة المناسبة قبل المتابعة.\n\nاحتفظ بسجل مفيد\n\nاحفظ الفواتير التي تتضمن التاريخ والمسافة والعمل المنجز والقطع المستخدمة. يساعد السجل المنتظم الفني على ملاحظة الأنماط وقد يسهل البيع مستقبلاً. اطلب شرحاً للأعمال الموصى بها وما يحتاج إلى اهتمام الآن وما يمكن تأجيله.\n\nضع خطة مع مستشارك\n\nتراعي مناقشة الصيانة الجيدة خصوصية سيارتك. شارك طريقة استخدامها والتغيرات الأخيرة والرحلات المخطط لها. في أبيكس موتورز نحول هذه التفاصيل إلى تقدير واضح ونطاق عمل متفق عليه وخطة يمكنك فهمها واتباعها.', ['Maintenance', 'Ownership'], ['صيانة', 'ملكية']),
  blog('before-you-buy-inspection-guide', 'Before you buy: look beyond the finish', 'قبل الشراء: انظر إلى ما وراء المظهر', 'The right questions and a structured inspection help you understand a vehicle before committing.', 'الأسئلة الصحيحة والفحص المنظم يساعدانك على فهم السيارة قبل اتخاذ القرار.', photos.mercedes, 1, '2026-08-22',
    'Start with the story\n\nA beautiful exterior is only one part of a vehicle’s story. Ask for available service records, ownership documentation, and details of significant repairs. Check that identification information is consistent across the vehicle and its documents. If something is unclear, request clarification before moving forward.\n\nSee the car in useful conditions\n\nInspect in daylight with enough time to look carefully. Note differences in panel fit, paint appearance, tire wear, and cabin condition. None of these observations alone provides a diagnosis, but they can point to questions worth asking. Try the controls and features that matter to your everyday use.\n\nBring in an independent perspective\n\nA pre-purchase inspection should have a defined scope and a written report. Ask what is accessible, whether electronic diagnostics and a road test are included, and what cannot be assessed without dismantling. The report should separate observed faults from items that need further investigation.\n\nConsider the first year of ownership\n\nLook beyond the purchase price. Upcoming scheduled maintenance, tire replacement, insurance, and registration can all affect the budget. A clear condition report helps you plan these costs. Give yourself time to decide, and have the agreed specification and sale terms recorded before you commit.',
    'ابدأ بتاريخ السيارة\n\nالمظهر الجميل جزء واحد من قصة السيارة. اطلب سجلات الصيانة المتاحة ووثائق الملكية وتفاصيل الإصلاحات المهمة. تحقق من تطابق بيانات التعريف في السيارة ووثائقها. وإذا وجدت أمراً غير واضح فاطلب توضيحه قبل المتابعة.\n\nعاين السيارة في ظروف مناسبة\n\nافحصها في ضوء النهار مع وقت كافٍ للملاحظة. انتبه إلى اختلافات تركيب الألواح ومظهر الطلاء وتآكل الإطارات وحالة المقصورة. لا تكفي أي ملاحظة منفردة للتشخيص لكنها قد تشير إلى أسئلة مهمة. جرّب أدوات التحكم والخصائص التي تحتاجها يومياً.\n\nاستعن برأي مستقل\n\nينبغي أن يكون لفحص ما قبل الشراء نطاق محدد وتقرير مكتوب. اسأل عما يمكن الوصول إليه وما إذا كان التشخيص الإلكتروني وتجربة القيادة مشمولين وما لا يمكن تقييمه دون تفكيك. ويجب أن يفصل التقرير بين الأعطال المرصودة وما يحتاج إلى بحث إضافي.\n\nفكر في السنة الأولى للملكية\n\nانظر إلى ما بعد سعر الشراء. فقد تؤثر الصيانة القادمة والإطارات والتأمين والتسجيل على الميزانية. يساعد تقرير الحالة الواضح على التخطيط لهذه التكاليف. امنح نفسك وقتاً للقرار وسجّل المواصفات وشروط البيع المتفق عليها قبل الالتزام.', ['Inspection', 'Buying'], ['فحص', 'شراء']),
  blog('a-better-finish-paint-protection', 'A better finish starts with better care', 'مظهر أجمل يبدأ بعناية أفضل', 'A practical guide to washing, paint correction, and choosing protection that fits your routine.', 'دليل عملي للغسيل ومعالجة الطلاء واختيار حماية تناسب روتينك.', photos.detail, 0, '2026-08-16',
    'Preparation makes the difference\n\nPaint protection works best on a properly prepared surface. Start with an assessment of the existing finish, then a wash method suited to the vehicle and the contamination present. Clean tools, suitable products, and careful drying help reduce the chance of introducing new marks.\n\nKnow what correction can achieve\n\nPolishing may improve clarity and reduce certain defects, but it removes a small amount of material. The appropriate approach depends on the paint condition, previous repairs, and the depth of the marks. Ask your detailer to explain the expected result and why a particular level of correction is suitable.\n\nChoose protection for your routine\n\nWaxes, sealants, and coatings have different preparation and maintenance needs. Discuss where the vehicle is parked, how often it is washed, and how much upkeep you want to undertake. No finish makes a vehicle immune to scratches, stone chips, or neglected contaminants.\n\nProtect the result with good habits\n\nFollow the product’s cure and care instructions. Remove contamination promptly using appropriate methods, avoid dry wiping dusty paint, and keep a regular gentle washing routine. A considered aftercare plan usually does more for long-term appearance than a single intensive session.',
    'التحضير يصنع الفرق\n\nتؤدي حماية الطلاء عملها بصورة أفضل على سطح مجهز جيداً. ابدأ بتقييم حالة الطلاء ثم اختر طريقة غسيل تناسب السيارة والملوثات الموجودة. تساعد الأدوات النظيفة والمنتجات المناسبة والتجفيف الحذر على تقليل احتمالات ظهور آثار جديدة.\n\nاعرف ما تحققه المعالجة\n\nقد يحسن التلميع الوضوح ويقلل بعض العيوب لكنه يزيل كمية صغيرة من المادة. يعتمد الأسلوب المناسب على حالة الطلاء والإصلاحات السابقة وعمق الآثار. اطلب من المختص شرح النتيجة المتوقعة وسبب ملاءمة مستوى المعالجة المقترح.\n\nاختر حماية تناسب روتينك\n\nللشمع ومواد العزل والطلاءات متطلبات مختلفة للتحضير والصيانة. ناقش مكان ركن السيارة وتكرار غسلها ومقدار العناية الذي تفضله. لا توجد حماية تجعل السيارة محصنة ضد الخدوش أو الحصى أو الملوثات المهملة.\n\nحافظ على النتيجة بعادات جيدة\n\nاتبع تعليمات الجفاف والعناية الخاصة بالمنتج. أزل الملوثات سريعاً بوسائل مناسبة وتجنب مسح الطلاء المغبر جافاً والتزم بغسيل لطيف منتظم. غالباً ما تفيد خطة العناية المستمرة المظهر أكثر من جلسة مكثفة واحدة.', ['Detailing', 'Paint care'], ['عناية بالمظهر', 'طلاء']),
  blog('choosing-parts-with-confidence', 'Choosing parts with confidence', 'اختر قطع سيارتك بثقة', 'Why compatibility, provenance, and installation matter as much as the part itself.', 'لماذا يهم التوافق والمصدر والتركيب بقدر أهمية القطعة نفسها.', photos.wheel, 0, '2026-08-10',
    'Start with the exact vehicle\n\nA model name alone is rarely enough to identify the right part. Production year, engine, transmission, equipment, and market specification can change what fits. Provide the vehicle identification details to your parts advisor, and confirm the exact requirement before placing an order.\n\nUnderstand the available options\n\nOriginal equipment and replacement parts can differ in manufacturer, specification, finish, and warranty terms. Ask where the part comes from and how its compatibility has been established. A reputable supplier should be able to explain the option clearly and supply the relevant product information.\n\nInclude the installation in the decision\n\nSome components need specialist fitting, software coding, calibration, or associated replacement items. Factor those requirements into the total cost and schedule. Safety-related systems deserve particular care, and installation should follow the correct technical procedure.\n\nKeep the paperwork\n\nRecord the part details, invoice, installation date, and any applicable coverage. Before ordering, confirm the lead time and return conditions, especially for special-order items. The best value comes from a correctly specified part, fitted well, with clear support if you need it.',
    'ابدأ ببيانات السيارة الدقيقة\n\nنادراً ما يكفي اسم الطراز لتحديد القطعة المناسبة. فسنة الإنتاج والمحرك وناقل الحركة والتجهيزات ومواصفات السوق قد تغير الملاءمة. زود مستشار القطع ببيانات تعريف السيارة وأكد المطلوب بدقة قبل الطلب.\n\nافهم الخيارات المتاحة\n\nقد تختلف القطع الأصلية والبديلة في المصنع والمواصفات والتشطيب وشروط الضمان. اسأل عن مصدر القطعة وكيف تم التحقق من توافقها. ينبغي للمورد الموثوق شرح الخيار بوضوح وتوفير المعلومات ذات الصلة.\n\nأدخل التركيب في القرار\n\nتحتاج بعض المكونات إلى تركيب متخصص أو برمجة أو معايرة أو قطع مصاحبة. ضع هذه المتطلبات ضمن التكلفة والجدول الزمني. تستحق الأنظمة المرتبطة بالسلامة عناية خاصة ويجب تركيبها وفق الإجراء الفني الصحيح.\n\nاحتفظ بالوثائق\n\nسجل بيانات القطعة والفاتورة وتاريخ التركيب وأي تغطية سارية. أكد وقت التوريد وشروط الإرجاع قبل الطلب، خاصة للقطع المطلوبة خصيصاً. تأتي القيمة الأفضل من قطعة مطابقة للمواصفات ومركبة جيداً مع دعم واضح عند الحاجة.', ['Parts', 'Quality'], ['قطع', 'جودة']),
  blog('prepare-for-the-long-drive', 'Ready for the road ahead', 'استعد للطريق القادم', 'A measured pre-journey routine for a more comfortable long-distance drive.', 'روتين مدروس قبل السفر لقيادة أكثر راحة في المسافات الطويلة.', photos.road, 0, '2026-08-04',
    'Plan ahead of the departure day\n\nArrange any due maintenance with enough time to address findings before you travel. Share your expected distance, passenger load, and driving conditions with your advisor. A pre-journey check can identify items that deserve attention, though it cannot guarantee a trouble-free trip.\n\nCheck the essentials\n\nFollow your vehicle handbook when checking tire condition and pressures, fluid levels, lights, and visibility. Make sure the spare wheel or mobility kit is present and usable where fitted. Know where the correct towing information and emergency equipment are kept.\n\nPrepare the cabin thoughtfully\n\nSecure luggage, keep essential documents accessible, and set your navigation before setting off. Plan sensible rest stops and allow flexibility for weather and traffic. Keep sufficient charge on your phone and carry the support numbers relevant to your route.\n\nRespond calmly to a change\n\nIf the car develops a concern, find a safe place to stop when possible and consult the handbook. Do not continue driving against a serious warning. For immediate danger, contact emergency services. For a vehicle issue in a safe location, seek appropriate professional assistance and describe the symptoms clearly.',
    'خطط قبل يوم الانطلاق\n\nرتب الصيانة المستحقة مع وقت كافٍ لمعالجة النتائج قبل السفر. شارك المسافة المتوقعة وعدد الركاب وظروف القيادة مع مستشارك. يمكن لفحص ما قبل الرحلة كشف أمور تحتاج إلى اهتمام لكنه لا يضمن رحلة خالية من الأعطال.\n\nراجع الأساسيات\n\nاتبع دليل السيارة عند فحص حالة الإطارات وضغطها ومستويات السوائل والأضواء والرؤية. تأكد من وجود الإطار الاحتياطي أو عدة الإصلاح وصلاحيتها إذا كانت مجهزة. واعرف مكان معلومات السحب ومعدات الطوارئ.\n\nجهز المقصورة بعناية\n\nثبّت الأمتعة واحتفظ بالوثائق المهمة في متناول اليد واضبط الملاحة قبل الانطلاق. خطط لاستراحات معقولة واترك مرونة للطقس والازدحام. حافظ على شحن الهاتف واحمل أرقام الدعم المناسبة لمسارك.\n\nتعامل بهدوء مع التغيرات\n\nإذا ظهرت مشكلة، ابحث عن مكان آمن للتوقف إن أمكن وراجع الدليل. لا تواصل القيادة مع تحذير خطير. عند وجود خطر مباشر اتصل بالطوارئ. ولمشكلة في مكان آمن اطلب مساعدة متخصصة واشرح الأعراض بوضوح.', ['Travel', 'Vehicle care'], ['سفر', 'عناية بالسيارة']),
  blog('what-makes-a-great-driving-experience', 'More than a destination', 'أكثر من مجرد وجهة', 'The considered details that make premium vehicle ownership feel personal.', 'التفاصيل المدروسة التي تجعل امتلاك سيارة فاخرة تجربة شخصية.', photos.porsche, 2, '2026-07-28',
    'A car should suit your everyday life\n\nPerformance figures and a striking profile can start a conversation, but daily comfort often determines lasting satisfaction. Think about the journeys you make most often, who travels with you, and the equipment you actually use. The right choice balances character with practical needs.\n\nMake the test drive meaningful\n\nAllow time to adjust the seat and controls. Assess visibility, cabin access, storage, and how the car feels on a suitable route. Ask about features you do not recognize. A considered test drive helps you understand whether the experience matches your expectations.\n\nGood ownership includes good support\n\nA clear handover should cover the controls, available documentation, maintenance schedule, and where to ask for help. After that, responsive communication and transparent service matter just as much as the first impression in the showroom.\n\nOur approach at Apex Motors\n\nWe believe automotive care should be personal, informed, and easy to understand. Whether you are choosing a vehicle, planning maintenance, or discussing a detail that matters to you, our role is to listen and provide clear next steps. Excellence is built through those everyday interactions.',
    'ينبغي أن تناسب السيارة حياتك اليومية\n\nقد تبدأ أرقام الأداء والتصميم اللافت الحوار، لكن الراحة اليومية غالباً ما تحدد الرضا المستمر. فكر في رحلاتك المعتادة ومن يرافقك والتجهيزات التي تستخدمها فعلياً. يوازن الاختيار المناسب بين الشخصية والاحتياجات العملية.\n\nاجعل تجربة القيادة مفيدة\n\nخصص وقتاً لضبط المقعد وأدوات التحكم. قيّم الرؤية وسهولة دخول المقصورة والتخزين وإحساس السيارة على طريق مناسب. اسأل عن الخصائص التي لا تعرفها. تساعد التجربة المدروسة على معرفة مدى توافق السيارة مع توقعاتك.\n\nالملكية الجيدة تشمل دعماً جيداً\n\nينبغي أن يشمل التسليم الواضح أدوات التحكم والوثائق المتاحة وجدول الصيانة وكيفية طلب المساعدة. وبعد ذلك يصبح التواصل السريع والخدمة الشفافة بأهمية الانطباع الأول في صالة العرض.\n\nنهجنا في أبيكس موتورز\n\nنؤمن بأن العناية بالسيارات يجب أن تكون شخصية وواعية وسهلة الفهم. سواء كنت تختار سيارة أو تخطط للصيانة أو تناقش تفصيلاً يهمك، فإن دورنا هو الاستماع وتقديم خطوات واضحة. يُبنى التميز من خلال هذه التفاعلات اليومية.', ['Apex Journal', 'Ownership'], ['مجلة أبيكس', 'ملكية']),
];

