const albumPhotos = [[photos.mercedes, photos.luxury, photos.interior, photos.bmw, photos.suv, photos.porsche], [photos.porsche, photos.red, photos.supercar, photos.bmw, photos.road, photos.mercedes], [photos.detail, photos.interior, photos.wheel, photos.mercedes, photos.service, photos.luxury], [photos.red, photos.porsche, photos.suv, photos.supercar, photos.bmw, photos.road]];
const captions = [['A considered silhouette', 'تصميم مدروس'], ['Details worth a closer look', 'تفاصيل تستحق التأمل'], ['Designed around the driver', 'تصميم يتمحور حول السائق'], ['A distinctive point of view', 'زاوية رؤية مميزة'], ['Ready for the next journey', 'استعداد للرحلة القادمة'], ['Excellence in every angle', 'تميّز من كل زاوية']];
