const faqItems = [
  ['arrange-viewing', 'Can I arrange a vehicle viewing and test drive?', 'هل يمكنني ترتيب معاينة وتجربة قيادة؟', 'Yes. Contact our team with the vehicle or type of car you are interested in. We will confirm availability, arrange a viewing, and explain any identification or license requirements for a test drive.', 'نعم. تواصل مع فريقنا وحدد السيارة أو النوع الذي يهمك. نؤكد التوافر ونرتب المعاينة ونوضح متطلبات الهوية أو الرخصة لتجربة القيادة.', 'Vehicle Sales', 'بيع السيارات'],
  ['book-maintenance', 'How do I book a maintenance appointment?', 'كيف أحجز موعد صيانة؟', 'Use our contact form or call the team. Share the vehicle model, year, mileage, and any concern you have noticed. Your advisor will confirm the appointment and explain the initial assessment.', 'استخدم نموذج التواصل أو اتصل بالفريق. شارك الطراز والسنة والمسافة وأي مشكلة لاحظتها. يؤكد مستشارك الموعد ويشرح التقييم الأولي.', 'Maintenance', 'الصيانة'],
  ['inspection-scope', 'What does a pre-purchase inspection include?', 'ماذا يشمل فحص ما قبل الشراء؟', 'The agreed scope normally covers accessible mechanical and visual checks, supported diagnostics, and a written findings report. Road testing depends on permission and conditions. We explain limitations before the inspection.', 'يشمل النطاق المتفق عليه عادة فحوصاً ميكانيكية وبصرية للأجزاء المتاحة وتشخيصاً مدعوماً وتقريراً مكتوباً. تعتمد تجربة القيادة على الموافقة والظروف. نشرح القيود قبل الفحص.', 'Inspection', 'الفحص'],
  ['detailing-duration', 'How long does a detailing appointment take?', 'كم تستغرق جلسة العناية بالمظهر؟', 'Timing depends on the size and condition of the vehicle and the selected treatment. A focused interior clean differs from multi-stage paint correction. We confirm the expected duration after assessing the vehicle.', 'تعتمد المدة على حجم السيارة وحالتها والمعالجة المختارة. يختلف تنظيف المقصورة عن معالجة الطلاء متعددة المراحل. نؤكد المدة المتوقعة بعد تقييم السيارة.', 'Detailing', 'العناية بالمظهر'],
  ['parts-compatibility', 'How do you check that a part fits my car?', 'كيف تتحققون من ملاءمة القطعة لسيارتي؟', 'We use the vehicle identification details and relevant specification to check compatibility. Please provide the model, year, and identification number when requesting a quotation. We confirm special-order terms before purchase.', 'نستخدم بيانات تعريف السيارة ومواصفاتها للتحقق من التوافق. يرجى تقديم الطراز والسنة ورقم التعريف عند طلب عرض السعر. نؤكد شروط الطلبات الخاصة قبل الشراء.', 'Parts', 'القطع'],
  ['roadside-coverage', 'Where is roadside assistance available?', 'أين تتوفر المساعدة على الطريق؟', 'Contact our team with your exact location and vehicle concern. We will confirm current coverage, operating availability, response expectations, and cost before arranging assistance. In an emergency, contact the emergency services first.', 'تواصل مع فريقنا وأرسل موقعك الدقيق والمشكلة. نؤكد التغطية والتوافر ووقت الاستجابة المتوقع والتكلفة قبل ترتيب المساعدة. في الطوارئ اتصل بخدمات الطوارئ أولاً.', 'Roadside', 'المساعدة على الطريق'],
  ['additional-work', 'Will you ask before carrying out additional work?', 'هل تطلبون موافقتي قبل تنفيذ أعمال إضافية؟', 'Yes. Your advisor will explain any additional findings, the recommended work, and the revised estimate. We seek your approval before proceeding with work outside the agreed scope.', 'نعم. يشرح مستشارك أي نتائج إضافية والعمل الموصى به والتقدير المعدل. نطلب موافقتك قبل تنفيذ أي عمل خارج النطاق المتفق عليه.', 'General', 'عام'],
  ['reschedule-appointment', 'Can I change or cancel my appointment?', 'هل يمكنني تعديل الموعد أو إلغاؤه؟', 'Please contact us as early as possible so we can offer another time and adjust our workshop schedule. Any terms applying to special-order parts or reserved services will be explained when you book.', 'يرجى التواصل في أقرب وقت لنقترح موعداً آخر ونعدل جدول الورشة. نوضح عند الحجز أي شروط تتعلق بالقطع المطلوبة خصيصاً أو الخدمات المحجوزة.', 'General', 'عام'],
];
data.faqs = faqItems.map(([slug, en, ar, de, da, category_en, category_ar]) => make(slug, en, ar, de, da, { category: category_en, category_en, category_ar }));
